/* Some browsers restore hash entries without our state object. The hash remains the fallback. */
addEventListener('popstate',event=>{if(event.state?.scene)return;const scene=location.hash.slice(1);if(['prologue','index','observe','recall','compare','discover','protocol'].includes(scene)){clearInterval(timerId);go(scene,{record:false})}});

const preview=new URLSearchParams(location.search);if(preview.has('preview')){const key=preview.get('work');if(works[key])state.work=key;root.dataset.work=state.work;const w=current(),t=workText();q('[data-art-image]').src=q('[data-compare-image]').src=q('[data-discover-image]').src=w.image;q('[data-art-title]').textContent=t.title;q('[data-art-meta]').textContent=t.meta;root.dataset.scene=preview.get('preview');requestAnimationFrame(()=>{if(root.dataset.scene==='recall')prepareDrawing(true);if(root.dataset.scene==='protocol')q('[data-credit]').textContent=t.credit})}

/* The first screen quietly previews the core gesture: looking leaves a trace. */
const prologueDoodle=q('[data-prologue-doodle]');let doodlePoint=null;
function sizePrologueDoodle(){const d=Math.min(devicePixelRatio||1,2),r=prologueDoodle.getBoundingClientRect();prologueDoodle.width=Math.round(r.width*d);prologueDoodle.height=Math.round(r.height*d);doodlePoint=null}
function leaveDoodle(event){if(root.dataset.scene!=='prologue'){doodlePoint=null;return}const r=prologueDoodle.getBoundingClientRect(),d=prologueDoodle.width/r.width,next={x:(event.clientX-r.left)*d,y:(event.clientY-r.top)*d};if(!doodlePoint){doodlePoint=next;return}const ctx=prologueDoodle.getContext('2d'),speed=Math.hypot(next.x-doodlePoint.x,next.y-doodlePoint.y);if(speed>90){doodlePoint=next;return}ctx.save();ctx.lineCap='round';ctx.strokeStyle=event.pointerType==='pen'?'#25211d':(next.x/r.width/d>.56?'#315c7c':'#a83329');ctx.globalAlpha=.16;ctx.lineWidth=Math.max(1.1,Math.min(4,3.4-speed*.025))*d;ctx.beginPath();ctx.moveTo(doodlePoint.x,doodlePoint.y);ctx.quadraticCurveTo((doodlePoint.x+next.x)/2+(Math.random()-.5)*2*d,(doodlePoint.y+next.y)/2+(Math.random()-.5)*2*d,next.x,next.y);ctx.stroke();for(let i=0;i<2;i++){ctx.globalAlpha=.055;ctx.fillStyle=ctx.strokeStyle;ctx.beginPath();ctx.arc(next.x+(Math.random()-.5)*9*d,next.y+(Math.random()-.5)*9*d,Math.random()*1.7*d,0,Math.PI*2);ctx.fill()}ctx.restore();doodlePoint=next}
sizePrologueDoodle();root.addEventListener('pointermove',leaveDoodle,{passive:true});addEventListener('resize',sizePrologueDoodle);

/* A dry pastel companion stroke makes the prologue gesture materially memorable. */
let pastelPoint=null;
function leavePastelTrace(event){if(root.dataset.scene!=='prologue'||(event.pointerType==='touch'&&!event.isPrimary)){pastelPoint=null;return}const r=prologueDoodle.getBoundingClientRect(),d=prologueDoodle.width/r.width,next={x:(event.clientX-r.left)*d,y:(event.clientY-r.top)*d};if(!pastelPoint){pastelPoint=next;return}const speed=Math.hypot(next.x-pastelPoint.x,next.y-pastelPoint.y);if(speed>110){pastelPoint=next;return}root.classList.add('has-trace');const ctx=prologueDoodle.getContext('2d'),blue=next.x<r.width*d*.55,color=blue?'#315c7c':'#a83329',pressure=event.pointerType==='touch'?.72:1;ctx.save();ctx.lineCap='round';for(let pass=0;pass<7;pass++){ctx.strokeStyle=color;ctx.globalAlpha=(.035+Math.random()*.045)*pressure;ctx.lineWidth=(5+Math.random()*13)*d;ctx.beginPath();ctx.moveTo(pastelPoint.x+(Math.random()-.5)*7*d,pastelPoint.y+(Math.random()-.5)*7*d);ctx.lineTo(next.x+(Math.random()-.5)*7*d,next.y+(Math.random()-.5)*7*d);ctx.stroke()}for(let i=0;i<6;i++){ctx.fillStyle=color;ctx.globalAlpha=(.055+Math.random()*.08)*pressure;ctx.beginPath();ctx.arc(next.x+(Math.random()-.5)*18*d,next.y+(Math.random()-.5)*18*d,(.35+Math.random()*1.7)*d,0,Math.PI*2);ctx.fill()}ctx.restore();pastelPoint=next}
